mapper.update:
UPDATE TRAVEL_PLAN
   SET START_DATE = #{startDate},
       END_DATE = #{endDate},
       VERSION_NO = VERSION_NO + 1,
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE PLAN_ID = #{planId}
   AND OWNER_MEMBER_ID = #{memberId}
   AND PLAN_STATUS = 'ACTIVE'
   AND VERSION_NO = #{versionNo}

UPDATE TRAVEL_PLAN
   SET TITLE = #{title},
       VISIBILITY = #{visibility},
       VERSION_NO = VERSION_NO + 1,
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE PLAN_ID = #{planId}
   AND OWNER_MEMBER_ID = #{memberId}
   AND PLAN_STATUS = 'ACTIVE'
   AND VERSION_NO = #{versionNo}

UPDATE TRAVEL_PLAN
   SET PUBLISH_STATUS = #{publishStatus},
       THUMBNAIL_IMG = COALESCE(THUMBNAIL_IMG, #{thumbnailImageUrl,jdbcType=VARCHAR}),
       VERSION_NO = VERSION_NO + 1,
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE PLAN_ID = #{planId}
   AND OWNER_MEMBER_ID = #{memberId}
   AND PLAN_STATUS = 'ACTIVE'
   AND VERSION_NO = #{versionNo}

UPDATE TRAVEL_PLAN
   SET THUMBNAIL_IMG = #{thumbnailImageUrl,jdbcType=VARCHAR}
 WHERE PLAN_ID = #{planId}
   AND PLAN_STATUS = 'ACTIVE'

UPDATE TRAVEL_PLAN
   SET PLAN_STATUS = 'DELETED',
       DELETED_AT = CURRENT_TIMESTAMP,
       DELETED_BY_MEMBER_ID = #{memberId},
       VERSION_NO = VERSION_NO + 1,
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE PLAN_ID = #{planId}
   AND OWNER_MEMBER_ID = #{memberId}
   AND PLAN_STATUS = 'ACTIVE'
   AND VERSION_NO = #{versionNo}

UPDATE TRAVEL_PLAN
   SET PLAN_STATUS = 'ACTIVE',
       DELETED_AT = NULL,
       DELETED_BY_MEMBER_ID = NULL,
       VERSION_NO = VERSION_NO + 1,
       UPDATED_AT = CURRENT_TIMESTAMP
 WHERE PLAN_ID = #{planId}
   AND OWNER_MEMBER_ID = #{memberId}
   AND PLAN_STATUS = 'DELETED'
   AND VERSION_NO = #{versionNo}
